import { forwardRef } from 'react';

const shimmer = `animation: shimmer 1.5s ease-in-out infinite;`;

const SkeletonBase = forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement> & { className?: string }>(
  ({ className = '', style, ...props }, ref) => (
    <div
      ref={ref}
      className={`bg-white/10 rounded ${shimmer} ${className}`}
      style={{ background: 'linear-gradient(90deg, rgba(255,255,255,0.05) 25%, rgba(255,255,255,0.1) 50%, rgba(255,255,255,0.05) 75%)', backgroundSize: '200% 100%', ...style }}
      {...props}
    />
  )
);
SkeletonBase.displayName = 'Skeleton';

export const Skeleton = Object.assign(SkeletonBase, {
  Text: ({ lines = 3, className = '', ...props }) => (
    <div className={className} {...props}>
      {Array.from({ length: lines }).map((_, i) => (
        <SkeletonBase key={i} className="h-4 w-full max-w-[80%] mb-2" />
      ))}
    </div>
  ),
  Card: ({ className = '', ...props }) => (
    <div className={`backdrop-blur-xl bg-white/5 border border-white/10 rounded-2xl p-6 space-y-4 ${className}`} {...props}>
      <div className="flex items-center gap-4">
        <SkeletonBase className="w-12 h-12 rounded-full" />
        <div className="flex-1 space-y-2">
          <SkeletonBase className="h-5 w-3/4" />
          <SkeletonBase className="h-4 w-1/2" />
        </div>
      </div>
      <SkeletonBase className="h-4 w-full" />
      <SkeletonBase className="h-4 w-5/6" />
    </div>
  ),
  Table: ({ rows = 5, columns = 4, className = '', ...props }) => (
    <div className={`backdrop-blur-xl bg-white/5 border border-white/10 rounded-2xl overflow-hidden ${className}`} {...props}>
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead className="bg-white/5">
            <tr>
              {Array.from({ length: columns }).map((_, i) => (
                <th key={i} className="p-3 text-left"><SkeletonBase className="h-4 w-24" /></th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-white/5">
            {Array.from({ length: rows }).map((_, r) => (
              <tr key={r}>
                {Array.from({ length: columns }).map((_, c) => (
                  <td key={c} className="p-3"><SkeletonBase className="h-4 w-full" /></td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  ),
  Avatar: ({ size = 'md', className = '', ...props }) => {
    const sizes = { xs: 'w-6 h-6', sm: 'w-8 h-8', md: 'w-10 h-10', lg: 'w-12 h-12', xl: 'w-16 h-16' };
    return <SkeletonBase className={`${sizes[size]} rounded-full ${className}`} {...props} />;
  },
  Button: ({ className = '', ...props }) => (
    <SkeletonBase className="h-10 px-6 rounded-lg ${className}" {...props} />
  ),
  Input: ({ className = '', ...props }) => (
    <SkeletonBase className="h-10 w-full rounded-lg ${className}" {...props} />
  ),
  Circle: ({ size = 40, className = '', ...props }) => (
    <SkeletonBase className={`w-[${size}px] h-[${size}px] rounded-full ${className}`} {...props} />
  ),
  Rectangle: ({ width = 200, height = 100, className = '', ...props }) => (
    <SkeletonBase className={`w-[${width}px] h-[${height}px] rounded-xl ${className}`} {...props} />
  ),
});
